    #Node Set Shade Smooth
    @smooth.setter
    def smooth( self, shade_smooth: Boolean = None):
        """Node Set Shade Smooth.
        
        Jump: True
        
        **Fixed inputs**
        - Node parameter 'domain' = 'FACE'
        
        **Computed inputs**
        - Socket 'Selection' = selection
        
        Parameters
        ----------
        shade_smooth : Boolean, optional
            Socket 'Shade Smooth' (default: None)
        
        """
        selection = self.get_selection()
        node = Node(
            'Set Shade Smooth',
            named_sockets={'ID_Geometry': self, 'ID_Selection': selection, 'ID_Shade Smooth': shade_smooth},
            domain='FACE')
        
        self._jump(node._out)

