        """Node Set Mesh Normal.
        
        Jump: True
        
        **Fixed inputs**
        - Node parameter 'mode' = 'FREE'
        - Node parameter 'domain' = 'FACE'
        
        Parameters
        ----------
        custom_normal : Vector, optional
            Socket 'Custom Normal' (default: None)
        
        """
        node = Node(
            'Set Mesh Normal',
            named_sockets={'ID_Mesh': self, 'ID_Custom Normal': custom_normal},
            mode='FREE',
            domain='FACE')
        
        self._jump(node._out)
